<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { createCategory, deleteCategory, listCategories, updateCategory, type CategoryInput } from '../api/books'
import { errorMessage } from '../utils/errors'
import type { Category } from '../types/domain'
const query = reactive({ name: '', page: 1, page_size: 20 }); const rows = ref<Category[]>([]); const count = ref(0); const loading = ref(false); const dialog = ref(false); const editing = ref<string | null>(null); const saving = ref(false)
const formRef = ref<FormInstance>(); const form = reactive<CategoryInput>({ name: '', description: '' })
const rules: FormRules = { name: [{ required: true, message: '请输入分类名称', trigger: 'blur' }, { validator: (_rule, value: string, callback: (error?: Error) => void) => value.trim() ? callback() : callback(new Error('分类名称不能为空白')), trigger: 'blur' }, { max: 100, message: '最多 100 个字符', trigger: 'blur' }], description: [{ max: 10000, message: '最多 10000 个字符', trigger: 'blur' }] }
async function load() { loading.value = true; try { const data = await listCategories({ name: query.name || undefined, page: query.page, page_size: query.page_size }); rows.value = data.results; count.value = data.count } catch (error) { ElMessage.error(errorMessage(error)) } finally { loading.value = false } }
function search() { query.page = 1; void load() }
function open(row?: Category) { editing.value = row?.id ?? null; form.name = row?.name ?? ''; form.description = row?.description ?? ''; dialog.value = true }
async function save() { if (!await formRef.value?.validate().catch(() => false)) return; saving.value = true; try { if (editing.value) await updateCategory(editing.value, { ...form }); else await createCategory({ ...form }); ElMessage.success('保存成功'); dialog.value = false; await load() } catch (error) { ElMessage.error(errorMessage(error)) } finally { saving.value = false } }
async function remove(row: Category) { try { await ElMessageBox.confirm(`确定删除分类「${row.name}」？存在图书引用时后端会拒绝。`, '二次确认', { type: 'warning', confirmButtonText: '确认删除', cancelButtonText: '取消' }); await deleteCategory(row.id); ElMessage.success('分类已删除'); if (rows.value.length === 1 && query.page > 1) query.page -= 1; await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(errorMessage(error)) } }
onMounted(load)
</script>
<template><div class="page-head"><div><h1>分类管理</h1><p>管理图书分类，已有图书引用的分类不能删除</p></div><el-button type="primary" @click="open()">新增分类</el-button></div><div class="panel"><div class="toolbar"><el-input v-model="query.name" placeholder="分类名称模糊查询" clearable @keyup.enter="search" /><el-button type="primary" @click="search">查询</el-button></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="name" label="名称" min-width="180" /><el-table-column prop="description" label="描述" min-width="260" show-overflow-tooltip /><el-table-column label="操作" width="145"><template #default="scope"><el-button link type="primary" @click="open(scope.row)">编辑</el-button><el-button link type="danger" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.page" :page-size="query.page_size" :total="count" layout="total, prev, pager, next" @current-change="load" /></div></div><el-dialog v-model="dialog" :title="editing ? '编辑分类' : '新增分类'" width="520px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="70px"><el-form-item label="名称" prop="name"><el-input v-model="form.name" maxlength="100" /></el-form-item><el-form-item label="描述" prop="description"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="10000" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
